// Format val countsStr = counts.map(_.toInt).mkString(", ") val speedsStr = speeds.map(s => f"$s%2.1f").mkString(", ")
Recorder.ew.write( s" lane_flow: [$countsStr] : lane_speed: [$speedsStr] : flow_total: [${total.toInt}] : ave_speed = [${f"$avgSpeed%2.1f"}]\n" ) end for Recorder.ew.write(s"\n================== ROW-WISE LANE STATS FOR SENSOR==================\n") //Recorder.ew.flush() end writeLaneIntervalStats
