    lazy val sensor1Total: Int = mainlineLaneTotals.sum
    lazy val onramp1Total: Int = onRampTotals(0)
    lazy val onramp2Total: Int = onRampTotals(1)
    lazy val offrampTotal: Int = offrampData(?, ramplaneIdx(0)).sum.toInt

    // ----------------------------------------------------------------------
