    // Vectorized vertical concatenation eliminates loops and duplicate storage
    private val muAllSources: MatrixD = muMainlineLanes ++ muRamps

    // Accessor extracts row on-demand and converts to Array[Double]
    def getMuForSource(i: Int): Array[Double] = muAllSources(i).toArray

    def getMainlineLaneTotals: Array[Int] = mainlineLaneTotals
    def getOnRampTotals: Array[Int] = onRampTotals

